s=s.replace('''/** The side of an island''','''/** The sea's sectors (§5 reveals the final island's): a grid of this many columns and as many rows. */
export const SECTOR_GRID = 3;

export interface Sector {
  /** 0 west to SECTOR_GRID - 1 east. */
  readonly column: number;
  /** 0 north to SECTOR_GRID - 1 south. */
  readonly row: number;
}

/**
 * The sector a tile lies in: column ⌊3 · tileX / widthTiles⌋, row ⌊3 · tileY / heightTiles⌋. On the 111-tile slice sea
 * the columns (and rows) are tiles 0–36, 37–73 and 74–110, so the map's mirror maps sectors onto sectors. Whatever
 * announces a sector (the intel module, the endgame reveal) must use this same formula.
 */
export function sectorOf(map: Pick<SeaMapDefinition, "widthTiles" | "heightTiles">, tileX: number, tileY: number): Sector {
  return { column: Math.floor((SECTOR_GRID * tileX) / map.widthTiles), row: Math.floor((SECTOR_GRID * tileY) / map.heightTiles) };
}

/**
 * The index of the socket that is the final island for a match: pure over the map and a 32-bit `secret`, an unsigned
 * integer the server draws from a cryptographic source for each match. Never pass the match's seed or anything else
 * public or derived from it: §3 requires that the final island cannot be recovered from a public seed, and the map is
 * public, so the secret is the only thing hiding the choice.
 *
 * The secret goes through the murmur3 finaliser (xor-shift 16, × 0x85ebca6b, xor-shift 13, × 0xc2b2ae35, xor-shift 16,
 * in `Math.imul` 32-bit arithmetic) before the reduction modulo the socket count, so every bit of the secret moves
 * the choice, not only its low bits. The finaliser permutes the 32-bit integers, so over all secrets each socket of a
 * power-of-two count is chosen equally often. It is a mixer, not a cryptographic hash: the secrecy comes from the
 * secret.
 */
export function chooseFinalSocket(map: Pick<SeaMapDefinition, "finalSockets">, secret: number): number {
  if (map.finalSockets.length === 0) throw new RangeError("the map has no final-island sockets");
  if (!Number.isInteger(secret) || secret < 0 || secret > 0xffffffff) throw new RangeError(`the secret must be an unsigned 32-bit integer, got ${secret}`);
  let mixed = secret;
  mixed ^= mixed >>> 16;
  mixed = Math.imul(mixed, 0x85ebca6b);
  mixed ^= mixed >>> 13;
  mixed = Math.imul(mixed, 0xc2b2ae35);
  mixed ^= mixed >>> 16;
  return (mixed >>> 0) % map.finalSockets.length;
}

/** The side of an island''')
