 * run of 14 tiles straight out to sea (the `sail-and-dock` browser route runs from 14 rows south of Palm Key's south
 * dock up to it).
 */
export function keepClearZones(map: SeaMapDefinition): readonly { label: string; tiles: readonly TilePoint[] }[] {
  const run = (from: TilePoint, dx: number, dy: number) => Array.from({ length: 15 }, (_, step) => ({ tileX: from.tileX + dx * step, tileY: from.tileY + dy * step }));
  const out: Record<string, readonly [number, number]> = { N: [0, -1], S: [0, 1], E: [1, 0], W: [-1, 0] };
  return [
    { label: "the hub", tiles: [map.hub] },
    ...map.spawnSlots.map((slot, index) => ({ label: `spawn slot ${index}`, tiles: [slot] })),
    ...map.docks.map((dock) => {
      const [dx, dy] = out[dock.side] ?? [0, 0];
      return { label: `${map.islands[dock.island]?.name ?? "?"} ${dock.side} dock or its run out to sea`, tiles: run(dock, dx, dy) };
    }),
    { label: "the out-of-sight row", tiles: Array.from({ length: 41 }, (_, step) => ({ tileX: map.hub.tileX - 20 + step, tileY: map.hub.tileY + 3 })) },
  ];
}

/**
 * Checks the hidden final-island sockets (§3, §5). Each is an islet of at most MAX_FINAL_SOCKET_SIDE_TILES a side
 * inside the map, overlapping no island or other socket, with land and no dock; its claim tile is open sea beside the
 * islet's land. Then: every claim tile is reachable by sea from every spawn slot within the longest-crossing target
 * (90 s) at full speed; every sector (`sectorOf` the claim tile) that holds a socket holds at least two, so revealing
 * the sector does not reveal the socket; each treasure circle holds at least MIN_TREASURE_CIRCLE_NAVIGABLE_TILES
 * navigable tiles; and no socket tile or claim tile lies within FINAL_SOCKET_KEEP_CLEAR_TILES of `keepClearZones`.
 */
export function validateFinalSockets(
  map: SeaMapDefinition,
  tuning: ShipTuning,
  rules: SeaMapRules = sliceSeaRules,
): ValidationResult<readonly FinalSocketReport[]> {
  const issues: string[] = [];
  const sockets = map.finalSockets;
  if (sockets.length !== rules.finalSockets) issues.push(`${sockets.length} final-island sockets, not ${rules.finalSockets}`);
  const name = (index: number) => `final socket ${index} at ${sockets[index]!.rect.tileX},${sockets[index]!.rect.tileY}`;

  sockets.forEach(({ rect, claimTile }, index) => {
    const where = name(index);
    if (rect.widthTiles > MAX_FINAL_SOCKET_SIDE_TILES || rect.heightTiles > MAX_FINAL_SOCKET_SIDE_TILES) {
      issues.push(`${where}: ${rect.widthTiles} × ${rect.heightTiles} tiles is larger than ${MAX_FINAL_SOCKET_SIDE_TILES} × ${MAX_FINAL_SOCKET_SIDE_TILES}`);
    }
    if (rect.tileX < 0 || rect.tileY < 0 || rect.tileX + rect.widthTiles > map.widthTiles || rect.tileY + rect.heightTiles > map.heightTiles) {
      issues.push(`${where}: outside the map`);
    }
    const others = [...map.islands.map((island) => ({ label: island.name, rect: island })), ...sockets.slice(index + 1).map((other, offset) => ({ label: name(index + 1 + offset), rect: other.rect }))];
    for (const other of others) {
      const apart =
        rect.tileX + rect.widthTiles <= other.rect.tileX ||
        other.rect.tileX + other.rect.widthTiles <= rect.tileX ||
        rect.tileY + rect.heightTiles <= other.rect.tileY ||
        other.rect.tileY + other.rect.heightTiles <= rect.tileY;
      if (!apart) issues.push(`${where}: overlaps ${other.label}`);
    }
    let land = 0;
    for (let tileY = rect.tileY; tileY < rect.tileY + rect.heightTiles; tileY++) {
      for (let tileX = rect.tileX; tileX < rect.tileX + rect.widthTiles; tileX++) {
        const kind = terrainAt(map, tileX, tileY);
        if (kind === Terrain.Land) land++;
        if (kind === Terrain.Dock) issues.push(`${where}: a dock at ${tileX},${tileY} (a final socket has none)`);
      }
    }
    if (land === 0) issues.push(`${where}: no land`);
    const beside = [
      [claimTile.tileX + 1, claimTile.tileY],
      [claimTile.tileX - 1, claimTile.tileY],
      [claimTile.tileX, claimTile.tileY + 1],
      [claimTile.tileX, claimTile.tileY - 1],
    ].some(([x, y]) => terrainAt(map, x!, y!) === Terrain.Land && insideIsland(rect, x!, y!));
    if (terrainAt(map, claimTile.tileX, claimTile.tileY) !== Terrain.Sea || insideIsland(rect, claimTile.tileX, claimTile.tileY) || !beside) {
      issues.push(`${where}: its claim tile ${claimTile.tileX},${claimTile.tileY} is not open sea beside the islet's land`);
    }
