  if (issues.length > 0) return { ok: false, issues };

  // Sectors: a revealed sector must leave at least two candidates.
  const sectors = sockets.map(({ claimTile }) => sectorOf(map, claimTile.tileX, claimTile.tileY));
  sectors.forEach((sector, index) => {
    const sharing = sectors.filter((other) => other.column === sector.column && other.row === sector.row).length;
    if (sharing < 2) issues.push(`${name(index)}: the only final socket in sector column ${sector.column}, row ${sector.row}; a sector holding one holds at least two`);
  });

  // Reachable from every spawn slot within the longest-crossing target.
  const spawnCosts = map.spawnSlots.map((slot) => seaPathCosts(map, slot.tileX, slot.tileY));
  const worstSpawns = sockets.map(({ claimTile }, index) => {
    let worst = { slot: 0, cost: 0 };
    spawnCosts.forEach((costs, slot) => {
      const cost = costs[claimTile.tileY * map.widthTiles + claimTile.tileX]!;
      if (cost === UNREACHABLE) issues.push(`${name(index)}: its claim tile ${claimTile.tileX},${claimTile.tileY} is not reachable by sea from spawn slot ${slot}`);
      else if (cost > worst.cost) worst = { slot, cost };
    });
    const seconds = travelSeconds(worst.cost, tuning);
    if (seconds > travelTargets.longestCrossingMaxSeconds) {
      issues.push(`${name(index)}: its claim tile is ${seconds} s from spawn slot ${worst.slot}, over ${travelTargets.longestCrossingMaxSeconds} s`);
    }
    return { slot: worst.slot, seconds };
  });

  // Enough sea in each treasure circle to stop in.
  const radius = TREASURE_CIRCLE_RADIUS_TILES;
  const circleCounts = sockets.map(({ claimTile }, index) => {
    let count = 0;
    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        if (dx * dx + dy * dy <= radius * radius && isNavigable(map, claimTile.tileX + dx, claimTile.tileY + dy)) count++;
      }
    }
    if (count < MIN_TREASURE_CIRCLE_NAVIGABLE_TILES) {
      issues.push(`${name(index)}: its treasure circle holds ${count} navigable tiles, fewer than ${MIN_TREASURE_CIRCLE_NAVIGABLE_TILES}`);
    }
    return count;
  });

  // Clear of what the running tests sail on.
  const zones = keepClearZones(map);
  const clear = FINAL_SOCKET_KEEP_CLEAR_TILES;
  sockets.forEach(({ rect, claimTile }, index) => {
    const tiles: TilePoint[] = [claimTile];
    for (let tileY = rect.tileY; tileY < rect.tileY + rect.heightTiles; tileY++) {
      for (let tileX = rect.tileX; tileX < rect.tileX + rect.widthTiles; tileX++) tiles.push({ tileX, tileY });
