      const near = zone.tiles.some((point) => tiles.some((tile) => (tile.tileX - point.tileX) ** 2 + (tile.tileY - point.tileY) ** 2 <= clear * clear));
      if (near) issues.push(`${name(index)}: within ${clear} tiles of ${zone.label}`);
    }
  });

  return issues.length > 0
    ? { ok: false, issues }
    : { ok: true, value: sockets.map((_, index) => ({ sector: sectors[index]!, worstSpawn: worstSpawns[index]!, circleNavigableTiles: circleCounts[index]! })) };
}''')
