      [claimTile.tileX - 1, claimTile.tileY],
      [claimTile.tileX, claimTile.tileY + 1],
      [claimTile.tileX, claimTile.tileY - 1],
    ].some(([x, y]) => terrainAt(map, x!, y!) === Terrain.Land && insideIsland(rect, x!, y!));
    if (terrainAt(map, claimTile.tileX, claimTile.tileY) !== Terrain.Sea || insideIsland(rect, claimTile.tileX, claimTile.tileY) || !beside) {
